<template><section class="page-card"><div class="page-header"><div><h1 class="page-title">角色管理</h1><p class="muted">为角色分配菜单与按钮权限，变更后由服务端立即生效。</p></div><el-button v-has-permi="'system:role:create'" type="primary" @click="openCreate">新增角色</el-button></div><ManagementToolbar @search="load" @reset="reset"><el-input v-model="filters.keyword" placeholder="角色编码或名称" clearable/><el-select v-model="filters.status" placeholder="状态" clearable><el-option label="启用" value="active"/><el-option label="停用" value="inactive"/></el-select></ManagementToolbar><div v-if="loading" class="loading-state"><el-icon class="is-loading"><Loading /></el-icon></div><el-table v-else :data="rows" border><el-table-column prop="roleCode" label="角色编码" min-width="150"/><el-table-column prop="roleName" label="角色名称" min-width="130"/><el-table-column prop="description" label="说明" min-width="180"/><el-table-column label="状态" width="90"><template #default="{row}"><StatusTag :status="row.status"/></template></el-table-column><el-table-column label="已授权菜单" width="120"><template #default="{row}">{{row.menuIds?.length || 0}}</template></el-table-column><el-table-column label="操作" width="250" fixed="right"><template #default="{row}"><div class="table-actions"><el-button v-has-permi="'system:role:update'" text type="primary" @click="openEdit(row)">编辑</el-button><el-button v-has-permi="'system:role:status'" text @click="toggleStatus(row)">{{row.status==='active'?'停用':'启用'}}</el-button><el-button v-has-permi="'system:role:assign-menu'" text @click="openMenus(row)">菜单授权</el-button><el-button v-has-permi="'system:role:delete'" text type="danger" :disabled="row.isBuiltin" @click="remove(row)">删除</el-button></div></template></el-table-column></el-table><ManagementDrawer v-model="drawer.open" :title="drawer.title" :loading="saving" @save="save"><el-form class="drawer-form" label-position="top"><el-form-item label="角色编码" required><el-input v-model="form.roleCode" :disabled="drawer.mode==='edit'"/><HelpIcon content="角色编码创建后不可修改，使用小写字母开头，可包含数字、冒号、下划线和连字符。"/></el-form-item><el-form-item label="角色名称" required><el-input v-model="form.roleName"/></el-form-item><el-form-item label="角色说明"><el-input v-model="form.description" type="textarea"/></el-form-item><el-form-item label="状态"><el-radio-group v-model="form.status"><el-radio value="active">启用</el-radio><el-radio value="inactive">停用</el-radio></el-radio-group></el-form-item><el-form-item v-if="drawer.assigning" label="菜单及按钮权限"><el-tree ref="treeRef" :data="menuTree" node-key="id" show-checkbox check-on-click-node :props="{label:'menuName',children:'children'}"/></el-form-item></el-form></ManagementDrawer></section></template>
<script setup>import { nextTick,onMounted,reactive,ref } from 'vue';import { ElMessage,ElMessageBox } from 'element-plus';import { request,query } from '@/api/http';import ManagementToolbar from '@/components/ManagementToolbar.vue';import ManagementDrawer from '@/components/ManagementDrawer.vue';import StatusTag from '@/components/StatusTag.vue';import HelpIcon from '@/components/HelpIcon.vue';const rows=ref([]),menuTree=ref([]),loading=ref(false),saving=ref(false),treeRef=ref();const filters=reactive({keyword:'',status:''});const drawer=reactive({open:false,title:'',mode:'create',id:null,assigning:false});const form=reactive({roleCode:'',roleName:'',description:'',status:'active'});async function load(){loading.value=true;try{rows.value=(await request({url:'/system/roles',params:query(filters)})).data||[]}catch(e){ElMessage.error(e.message)}finally{loading.value=false}}async function loadMenus(){menuTree.value=(await request({url:'/system/menus'})).data?.tree||[]}function reset(){Object.assign(filters,{keyword:'',status:''});load()}function resetForm(){Object.assign(form,{roleCode:'',roleName:'',description:'',status:'active'})}function openCreate(){resetForm();Object.assign(drawer,{open:true,title:'新增角色',mode:'create',id:null,assigning:false})}function openEdit(row){resetForm();Object.assign(form,{roleCode:row.roleCode,roleName:row.roleName,description:row.description||'',status:row.status});Object.assign(drawer,{open:true,title:'编辑角色',mode:'edit',id:row.id,assigning:false})}async function openMenus(row){openEdit(row);drawer.title='分配菜单权限';drawer.assigning=true;await nextTick();treeRef.value.setCheckedKeys(row.menuIds||[])}async function save(){if(!form.roleCode||!form.roleName)return ElMessage.warning('请填写角色编码和名称。');saving.value=true;try{if(drawer.mode==='create')await request({method:'post',url:'/system/roles',data:form});else{await request({method:'put',url:`/system/roles/${drawer.id}`,data:form});if(drawer.assigning)await request({method:'put',url:`/system/roles/${drawer.id}/menus`,data:{menuIds:treeRef.value.getCheckedKeys()}})}ElMessage.success('保存成功。');drawer.open=false;load()}catch(e){ElMessage.error(e.message)}finally{saving.value=false}}async function toggleStatus(row){try{await ElMessageBox.confirm(`确定${row.status==='active'?'停用':'启用'}角色“${row.roleName}”吗？`,'状态确认',{type:'warning'});await request({method:'patch',url:`/system/roles/${row.id}/status`,data:{status:row.status==='active'?'inactive':'active'}});ElMessage.success('状态已更新。');load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message)}}async function remove(row){try{await ElMessageBox.confirm('仅无用户关联的非内置角色允许删除；通常建议停用。是否继续？','删除角色',{type:'warning'});await request({method:'delete',url:`/system/roles/${row.id}`});ElMessage.success('角色已删除。');load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message)}}onMounted(async()=>{await Promise.all([load(),loadMenus()])});</script>
